public class SinMetodos {
    public static void main(String[] args) {
        // Calcular area de rectangulo
        double base1 = 10, altura1 = 5;
        double area1 = base1 * altura1;
        System.out.printf("Area rectangulo: %.2f%n", area1);

        // Calcular area de circulo
        double radio1 = 3;
        double area2 = Math.PI * radio1 * radio1;
        System.out.printf("Area circulo: %.2f%n", area2);

        // Calcular area de triangulo
        double base2 = 8, altura2 = 6;
        double area3 = (base2 * altura2) / 2;
        System.out.printf("Area triangulo: %.2f%n", area3);

        // --- Mismo calculo, otros valores ---
        double base3 = 15, altura3 = 10;
        double area4 = base3 * altura3;
        System.out.printf("Area rectangulo 2: %.2f%n", area4);

        double radio2 = 7;
        double area5 = Math.PI * radio2 * radio2;
        System.out.printf("Area circulo 2: %.2f%n", area5);
    }
}

public class ConMetodos {

    static double calcularAreaRectangulo(double base, double altura) {
        return base * altura;
    }

    static double calcularAreaCirculo(double radio) {
        return Math.PI * radio * radio;
    }

    static double calcularAreaTriangulo(double base, double altura) {
        return (base * altura) / 2;
    }

    public static void main(String[] args) {
        System.out.printf("Area rectangulo: %.2f%n",
            calcularAreaRectangulo(10, 5));
        System.out.printf("Area circulo: %.2f%n",
            calcularAreaCirculo(3));
        System.out.printf("Area triangulo: %.2f%n",
            calcularAreaTriangulo(8, 6));

        // Reutilizamos los mismos metodos con otros valores
        System.out.printf("Area rectangulo 2: %.2f%n",
            calcularAreaRectangulo(15, 10));
        System.out.printf("Area circulo 2: %.2f%n",
            calcularAreaCirculo(7));
    }
}

public class CalculadoraBasica {

    // Metodo que suma dos enteros
    static int sumar(int a, int b) {
        return a + b;
    }

    // Metodo que resta dos enteros
    static int restar(int a, int b) {
        return a - b;
    }

    // Metodo que multiplica dos enteros
    static int multiplicar(int a, int b) {
        return a * b;
    }

    // Metodo que divide dos doubles
    static double dividir(double a, double b) {
        if (b == 0) {
            System.out.println("Error: division por cero.");
            return 0;
        }
        return a / b;
    }

    // Metodo que no devuelve nada (void)
    static void mostrarResultado(String operacion, double resultado) {
        System.out.printf("%s = %.2f%n", operacion, resultado);
    }

    public static void main(String[] args) {
        int x = 10, y = 3;

        mostrarResultado(x + " + " + y, sumar(x, y));
        mostrarResultado(x + " - " + y, restar(x, y));
        mostrarResultado(x + " * " + y, multiplicar(x, y));
        mostrarResultado(x + " / " + y, dividir(x, y));
    }
}

