public class CalculadoraRefactorizada {
    static double sumar(double a, double b) { return a + b; }
    static double restar(double a, double b) { return a - b; }
    static double multiplicar(double a, double b) { return a * b; }
    static double dividir(double a, double b) {
        if (b == 0) throw new ArithmeticException("Division por cero");
        return a / b;
    }

    public static void main(String[] args) {
        double a = 10, b = 3;
        System.out.printf("%.2f + %.2f = %.2f%n", a, b, sumar(a, b));
        System.out.printf("%.2f - %.2f = %.2f%n", a, b, restar(a, b));
        System.out.printf("%.2f * %.2f = %.2f%n", a, b, multiplicar(a, b));
        System.out.printf("%.2f / %.2f = %.4f%n", a, b, dividir(a, b));
    }
}

public class AreasGeometricas {
    static double rectangulo(double base, double altura) {
        assert base > 0 : "La base debe ser positiva";
        assert altura > 0 : "La altura debe ser positiva";
        return base * altura;
    }

    static double circulo(double radio) {
        assert radio > 0 : "El radio debe ser positivo";
        return Math.PI * radio * radio;
    }

    static double triangulo(double base, double altura) {
        assert base > 0 : "La base debe ser positiva";
        assert altura > 0 : "La altura debe ser positiva";
        return (base * altura) / 2;
    }

    static double trapecio(double baseMayor, double baseMenor, double altura) {
        assert baseMayor > 0 : "La base mayor debe ser positiva";
        assert baseMenor > 0 : "La base menor debe ser positiva";
        assert baseMayor > baseMenor : "La base mayor debe ser mayor que la menor";
        assert altura > 0 : "La altura debe ser positiva";
        return ((baseMayor + baseMenor) * altura) / 2;
    }

    public static void main(String[] args) {
        System.out.printf("Rectangulo: %.2f%n", rectangulo(10, 5));
        System.out.printf("Circulo: %.2f%n", circulo(3));
        System.out.printf("Triangulo: %.2f%n", triangulo(8, 6));
        System.out.printf("Trapecio: %.2f%n", trapecio(10, 6, 4));
    }
}

