public class ConversionTemperaturas {
    static double celsiusAFahrenheit(double celsius) {
        return celsius * 9.0 / 5 + 32;
    }

    static double fahrenheitACelsius(double fahrenheit) {
        return (fahrenheit - 32) * 5.0 / 9;
    }

    public static void main(String[] args) {
        double[] celsius = {0, 20, 37, 100};

        for (double c : celsius) {
            double f = celsiusAFahrenheit(c);
            System.out.printf("%.1f C = %.1f F%n", c, f);
        }

        System.out.println();

        double[] fahrenheit = {32, 68, 98.6, 212};
        for (double f : fahrenheit) {
            double c = fahrenheitACelsius(f);
            System.out.printf("%.1f F = %.1f C%n", f, c);
        }
    }
}

public class NormalizarValor {
    static double normalizar(double valor) {
        if (valor < 0) return 0;
        if (valor > 10) return 10;
        return valor;
    }

    public static void main(String[] args) {
        double nota1 = -5.0;
        double nota2 = 15.0;
        double nota3 = 7.5;

        System.out.printf("Original: %.1f -> Normalizado: %.1f%n", nota1, normalizar(nota1));
        System.out.printf("Original: %.1f -> Normalizado: %.1f%n", nota2, normalizar(nota2));
        System.out.printf("Original: %.1f -> Normalizado: %.1f%n", nota3, normalizar(nota3));

        System.out.println();
        System.out.println("Variables originales sin cambios:");
        System.out.println("nota1 = " + nota1); // Sigue valiendo -5.0
        System.out.println("nota2 = " + nota2); // Sigue valiendo 15.0
        System.out.println("nota3 = " + nota3); // Sigue valiendo 7.5
    }
}

