El **ámbito** (scope) de una variable es la zona del código donde esa variable es accesible (se puede leer y modificar). En Java, el ámbito está determinado por dónde se declara la variable.

Hay tres tipos principales de ámbitos:

**1. Variable local**: se declara dentro de un método, constructor o bloque. Solo existe dentro de ese bloque.

```java
static void miMetodo() {
    int x = 10; // x solo existe aqui dentro
    System.out.println(x);
}
// Fuera de miMetodo, x no existe
```

**2. Parámetro**: es como una variable local que se inicializa con el valor del argumento.

```java
static void saludar(String nombre) { // nombre es local al metodo
    System.out.println("Hola " + nombre);
}
```

**3. Variable de clase (campo)**: se declara fuera de cualquier método, dentro de la clase. Existe durante toda la vida del objeto o de la clase (si es static).

```java
public class MiClase {
    static int contador = 0; // Variable de clase

    static void incrementar() {
        contador++; // Accede a la variable de clase
    }
}
```

public class AmbitoVariables {

    // Variable de clase (static): accesible desde cualquier metodo estatico
    static String nombrePrograma = "Mi Programa";
    static int contadorGlobal = 0;

    static void metodoA() {
        // Variable local a metodoA
        int x = 10;
        System.out.println("metodoA: x = " + x);
        System.out.println("metodoA: nombrePrograma = " + nombrePrograma);

        contadorGlobal++; // Modifica la variable de clase
    }

    static void metodoB() {
        // Variable local a metodoB
        int y = 20;
        System.out.println("metodoB: y = " + y);
        // System.out.println(x); // ERROR: x no existe aqui

        contadorGlobal++; // Modifica la variable de clase
    }

    static void metodoConParametro(String texto) {
        // 'texto' es una variable local (parametro)
        System.out.println("metodoConParametro: texto = " + texto);
        // System.out.println(y); // ERROR: y no existe aqui
    }

    public static void main(String[] args) {
        // Variable local a main
        int z = 30;

        metodoA();
        metodoB();
        metodoConParametro("Hola mundo");

        System.out.println();
        System.out.println("main: z = " + z);
        System.out.println("main: nombrePrograma = " + nombrePrograma);
        System.out.println("main: contadorGlobal = " + contadorGlobal);

        // System.out.println(x); // ERROR: x no existe en main
    }
}

public class Shadowing {

    static int contador = 100; // Variable de clase

    static void incrementar(int cantidad) {
        // 'cantidad' es local y no tiene nada que ver con 'contador'
        contador += cantidad;
        System.out.println("Dentro de incrementar: contador = " + contador);
    }

    static void resetear() {
        int contador = 0; // Shadowing: esta variable local oculta la de clase
        System.out.println("Dentro de resetear: contador local = " + contador);
        // La variable de clase NO se modifica porque 'contador' aqui es la local
        System.out.println("Dentro de resetear: contador de clase = " + Shadowing.contador);
    }

    public static void main(String[] args) {
        System.out.println("Inicial: contador = " + contador);

        incrementar(10);
        System.out.println("Despues de incrementar: contador = " + contador);

        resetear();
        System.out.println("Despues de resetear: contador = " + contador);
        // El contador de clase sigue valiendo 110, no 0
    }
}

public class Constantes {

    // Constantes de clase
    static final double PI = 3.141592653589793;
    static final int DIAS_SEMANA = 7;
    static final String SEPARADOR = "=".repeat(40);

    static double calcularAreaCirculo(double radio) {
        return PI * radio * radio;
    }

    static String getNombreDia(int numero) {
        final String[] DIAS = {
            "Lunes", "Martes", "Miercoles",
            "Jueves", "Viernes", "Sabado", "Domingo"
        };

        if (numero < 1 || numero > DIAS_SEMANA) {
            return "No valido";
        }
        return DIAS[numero - 1];
    }

    public static void main(String[] args) {
        System.out.println(SEPARADOR);
        System.out.println("CONSTANTES EN JAVA");
        System.out.println(SEPARADOR);
        System.out.println();

        System.out.printf("PI = %.15f%n", PI);
        System.out.println("Dias de la semana: " + DIAS_SEMANA);
        System.out.println();

        // Calcular areas
        double[] radios = {1, 2, 3, 5, 10};
        for (double r : radios) {
            System.out.printf("Area del circulo con radio %.0f: %.2f%n",
                r, calcularAreaCirculo(r));
        }

        System.out.println();

        // Mostrar dias
        for (int i = 1; i <= DIAS_SEMANA; i++) {
            System.out.println("Dia " + i + ": " + getNombreDia(i));
        }
    }
}

