public class EjemploAmbito {
    // 'global' es VARIABLE DE CLASE: accesible desde cualquier metodo estatico
    static int global = 10;

    static void metodo(int parametro) {
        // 'parametro' es VARIABLE LOCAL (parametro): accesible solo en este metodo
        // 'local' es VARIABLE LOCAL: accesible solo en este metodo
        int local = 5;
        System.out.println("global: " + global);   // OK: variable de clase
        System.out.println("parametro: " + parametro); // OK: variable local
