        System.out.println("Valor inicial: " + getValor());

        incrementar();
        incrementar();
        incrementar();
        System.out.println("Despues de 3 incrementos: " + getValor());

        decrementar();
        System.out.println("Despues de 1 decremento: " + getValor());

