public class UtilidadesTexto {

    // Repetir un texto N veces
    static String repetir(String texto, int veces) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < veces; i++) {
            sb.append(texto);
        }
        return sb.toString();
    }

    // Repetir con separador (sobrecarga)
    static String repetir(String texto, int veces, String separador) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < veces; i++) {
            sb.append(texto);
            if (i < veces - 1) {
                sb.append(separador);
            }
        }
        return sb.toString();
    }

    // Truncar texto a N caracteres
    static String truncar(String texto, int maxLongitud) {
        if (texto.length() <= maxLongitud) {
            return texto;
        }
        return texto.substring(0, maxLongitud) + "...";
    }

    // Truncar con sufijo personalizado (sobrecarga)
    static String truncar(String texto, int maxLongitud, String sufijo) {
        if (texto.length() <= maxLongitud) {
            return texto;
        }
        return texto.substring(0, maxLongitud) + sufijo;
    }

    // Rellenar texto con caracteres
    static String rellenar(String texto, int longitudTotal, char caracter) {
        while (texto.length() < longitudTotal) {
            texto = caracter + texto;
        }
        return texto;
    }

    public static void main(String[] args) {
        // Repeticion
        System.out.println(repetir("=", 30));
        System.out.println(repetir("*-", 5, " "));

        System.out.println();

        // Truncar
        String textoLargo = "Este es un texto muy largo que necesita ser truncado";
        System.out.println(truncar(textoLargo, 20));
        System.out.println(truncar(textoLargo, 20, " >>"));

        System.out.println();

        // Rellenar
        System.out.println(rellenar("42", 8, '0'));
        System.out.println(rellenar("Hola", 15, '.'));
    }
}

Java NO permite valores por defecto en parámetros como otros lenguajes (Python, C++, etc.). La sobrecarga es la forma de simular este comportamiento:

```java
// En Python (no se puede en Java):
# def saludar(nombre, idioma="es"):

// En Java: usar sobrecarga
static void saludar(String nombre) {
    saludar(nombre, "es"); // Llama a la version completa
}

static void saludar(String nombre, String idioma) {
    if (idioma.equals("es")) {
        System.out.println("Hola, " + nombre);
    } else {
        System.out.println("Hello, " + nombre);
    }
}
```

La versión sin el segundo parámetro usa un valor por defecto llamando a la versión completa. Este patrón es muy común en la API estándar de Java.

public class ValoresPorDefecto {

    // Version completa: todos los parametros
    static void crearInforme(String titulo, String alumno, int ancho, char relleno) {
        String separador = String.valueOf(relleno).repeat(ancho);
        System.out.println(separador);
        System.out.printf("%" + (ancho / 2) + "s%s%n", "", titulo);
        System.out.println(separador);
        System.out.printf("Alumno: %s%n", alumno);
        System.out.println(separador);
    }

    // Sobrecarga: titulo y alumno con valores por defecto
    static void crearInforme(String titulo, String alumno) {
        crearInforme(titulo, alumno, 40, '=');
    }

    // Sobrecarga: solo titulo
    static void crearInforme(String titulo) {
        crearInforme(titulo, "Sin especificar", 40, '=');
    }

    public static void main(String[] args) {
        // Llamada completa
        crearInforme("INFORME 1", "Ana Garcia", 35, '*');

        System.out.println();

        // Llamada con valores por defecto
        crearInforme("INFORME 2", "Carlos Ruiz");

        System.out.println();

        // Llamada minima
        crearInforme("INFORME 3");
    }
}

