public class Texto {
    static String recortar(String texto, int maxLong) {
        if (texto.length() <= maxLong) return texto;
        return texto.substring(0, maxLong);
    }

    static String recortar(String texto, int maxLong, String sufijo) {
        if (texto.length() <= maxLong) return texto;
        return texto.substring(0, maxLong) + sufijo;
    }

    static boolean contiene(String texto, String busqueda) {
        return texto.contains(busqueda);
    }

    static boolean contiene(String texto, char caracter) {
        return texto.indexOf(caracter) >= 0;
    }

    public static void main(String[] args) {
        String frase = "Java es un lenguaje de programacion orientado a objetos";

        System.out.println("Original: " + frase);
        System.out.println("Recortar 20: \"" + recortar(frase, 20) + "\"");
        System.out.println("Recortar 20 + sufijo: \"" + recortar(frase, 20, "...") + "\"");
        System.out.println();
        System.out.println("Contiene \"lenguaje\": " + contiene(frase, "lenguaje"));
        System.out.println("Contiene 'x': " + contiene(frase, 'x'));
    }
}
